"""Only P11: produce own analysis/protocol first, then reflect those own results."""
import copy,hashlib,json
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path.cwd();OWN=Path(__file__).resolve().parent;BASE=OWN.parent;OLD=BASE/'remediation-v2';NATIVE=BASE/'native-preparation-v1';REL=OWN.relative_to(ROOT).as_posix()
def load(p):return json.loads(p.read_text())
def write(n,x):
 p=OWN/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def bind(p):
 b=p.read_bytes();return dict(path=p.relative_to(ROOT).as_posix(),sha256='sha256:'+hashlib.sha256(b).hexdigest(),bytes=len(b))
def pair(de,en):return dict(de=de,en=en)
assert not (OWN/'targeted-p11-own-results.first.freeze.json').exists()
materials=load(OLD/'fourteen-whole-twenty-nine-bilingual-cases.author-candidate.json');before=copy.deepcopy(materials);e=materials['entries'][10];ID=e['goalId'];assert ID=='8375310d-1f7e-542d-9969-55ad4bd37f7c'
exps=[dict(id='essential-1',essentialUnderstandingDe='Die lernende Person muss zunächst eigene nachvollziehbare Ergebnisse und ein eigenes Auswertungs-/Entscheidungsprotokoll erzeugen und danach genau diese Ergebnisse auf Gültigkeit reflektieren.',essentialUnderstandingEn='The learner must first produce their own traceable results and their own analysis/decision record, then reflect the validity of those specific results.',observablePerformanceDe='Erstelle eigene korrigierte Ergebnistabelle bzw. eigene Modellrechnung aus Rohkarten, dokumentiere Regeln und Entscheidungen und beurteile anschließend die Gültigkeit deiner eigenen Auswertung.',observablePerformanceEn='Produce your own corrected results table or model calculation from raw cards, document rules and decisions, then assess the validity of your own analysis.'),dict(id='essential-2',essentialUnderstandingDe='Eigene Auswertungsentscheidungen können systematische Fehler, zufällige Variation oder Störvariablen verschieden behandeln; der Einfluss auf eigene Schlussfolgerungen muss explizit bleiben.',essentialUnderstandingEn='Own analysis decisions treat systematic errors, random variation and confounders differently; their effects on one’s own conclusions must remain explicit.',observablePerformanceDe='Identifiziere Fehlerquellen deines eigenen Analysewegs, begründe deine gewählte Korrektur/Datenauswahl und revidiere die eigenen Ergebnisse und Entscheidungen bei einem neuen Befund.',observablePerformanceEn='Identify error sources in your own analysis, justify your chosen correction/data selection and revise your own results and decisions after new evidence.'),dict(id='essential-3',essentialUnderstandingDe='Das eigene Modell-/Analyseprotokoll erklärt nur ausgewählte biologische Beziehungen unter dokumentierten Annahmen; Reflexion muss Nutzen und Grenzen der eigenen Modellwahl diskutieren.',essentialUnderstandingEn='One’s own model/analysis record explains selected biological relationships under documented assumptions; reflection must discuss the usefulness and limits of that own model choice.',observablePerformanceDe='Formuliere eine begrenzte eigene Modellentscheidung und Ergebnisinterpretation, prüfe ihre Vorhersage und dokumentiere eine begründete eigene Revision, ohne fehlende Messwerte oder praktische Durchführung zu erfinden.',observablePerformanceEn='Formulate your own bounded model decision and result interpretation, test its prediction and record a justified own revision without inventing missing measurements or physical performance.')]
e['expectations']=exps
a,b=e['authoredCases'];assert [a['caseId'],b['caseId']]==['validity-sensor','validity-leaf-model']
a['material']=pair(
 'Konstruierte Rohkarten für deine eigene Auswertung: Drei unabhängige Wasserpflanzen-Modellansätze bei 20 °C haben nach Beleuchtung die Sensor-Endanzeigen S1=7,9, S2=8,0, S3=8,1 mg/L. Unmittelbar davor und danach zeigt derselbe Sensor bei denselben Bedingungen jeweils 8,0 mg/L für eine Referenz mit Sollwert 7,0 mg/L. Anfangssauerstoff, Atmung, Gasaustausch und Messdauer wurden nicht erhoben. Der leere eigene Protokollauftrag hat Spalten Rohanzeige, gewählte Korrekturregel, eigener korrigierter Wert, Begründung und Aussagegrenze. Eine vorgeschlagene Erklärung behauptet: die Endkonzentration sei allein Fotosyntheseproduktion. Alle Karten sind fiktiv; du erzeugst eigene Analyseergebnisse, keine neuen physisch gemessenen Daten.',
 'Constructed raw cards for your own analysis: three independent aquatic-plant model setups at 20 °C yield endpoint sensor readings S1=7.9, S2=8.0, S3=8.1 mg/L after illumination. Immediately before and after, under matching conditions, the same sensor reads 8.0 mg/L for a reference whose specified value is 7.0 mg/L. Starting oxygen, respiration, gas exchange and measurement duration were not recorded. Your blank record requires columns for raw reading, chosen correction rule, your corrected value, justification and claim boundary. A proposed explanation calls endpoint concentration solely photosynthetic production. All cards are fictitious: you produce your own analysis results, not newly measured physical data.')
a['task']=pair(
 'Erzeuge zuerst selbst eine vollständige korrigierte Ergebnistabelle, Mittelwert und Spannweite; schreibe dein eigenes Entscheidungsprotokoll mit ausgewählter Kalibrierregel und begrenzter Ergebnisinterpretation. Reflektiere danach ausdrücklich deine eigenen erzeugten Werte und deine eigenen Entscheidungen: Gültigkeit, systematischer Fehler versus Streuung, fehlende Variablen, Nutzen/Grenzen deiner Erklärung. Eine allgemeine Kritik der bereitgestellten Behauptung ohne eigene Auswertung erfüllt den Auftrag nicht.',
 'First produce your own complete corrected results table, mean and range, and write your own decision record with a selected calibration rule and bounded interpretation. Then explicitly reflect your own generated values and decisions: validity, systematic error versus spread, missing variables and the usefulness/limits of your explanation. General criticism of the supplied claim without your own analysis does not satisfy the task.')
a['workedResponse']=pair(
 'Mein eigenes Auswertungsprotokoll: Die zwei passenden Referenzanzeigen ergeben 8,0−7,0=+1,0 mg/L Offset. Ich entscheide mich unter der dokumentierten Stabilitäts-/20-°C-Annahme für korrigiert=roh−1,0 und erhalte selbst die Tabelle S1:7,9→6,9; S2:8,0→7,0; S3:8,1→7,1 mg/L. Ich bewahre die Rohspalte. Mein eigener Mittelwert ist (6,9+7,0+7,1)/3=7,0 mg/L, die Spannweite 0,2 mg/L. Meine Ergebnisentscheidung lautet: berichtbar sind korrigierte Endkonzentrationen unter diesen Bedingungen, keine Sauerstoffzunahme oder Fotosyntheserate. Reflexion meines eigenen Vorgehens: Die Korrektur ist aufgrund der passenden Referenzen nachvollziehbar, aber ihre Gültigkeit hängt an stabiler Kalibrierung; kleine Streuung beweist nicht Genauigkeit. Ich habe einen systematischen Offset korrigiert, nicht zufällige Streuung beseitigt. Mein Mittelwert ersetzt keine fehlenden Anfangswerte und erlaubt keine Ursache allein durch Fotosynthese. Ein Modell mit Fotosynthese als möglichem Eintrag ist nützlich, mein Anspruch muss jedoch Atmung und Austausch als nicht bestimmte Beiträge offen halten. Ich verwerfe deshalb meine mögliche weitergehende Produktionsdeutung und plane für eine solche Frage Anfang/Ende, Zeit und Kontrollen; ich erfinde sie nicht nachträglich. Das ist eine ausgearbeitete eigene Analyse-Modellantwort und keine hier ausgeführte physische Messung.',
 'My own analysis record: both matching reference checks give an 8.0−7.0=+1.0 mg/L offset. Under the documented stability/20 °C assumption I choose corrected=raw−1.0 and produce my own table S1:7.9→6.9; S2:8.0→7.0; S3:8.1→7.1 mg/L, retaining the raw column. My mean is (6.9+7.0+7.1)/3=7.0 mg/L and the range is 0.2 mg/L. My result decision is to report corrected endpoints under these conditions, not oxygen increase or photosynthesis rate. Reflecting my own procedure: matching references make my correction traceable, but validity relies on stable calibration; small spread does not prove accuracy. I corrected a systematic offset rather than removing random spread. My mean cannot supply missing initial values or establish photosynthesis as sole cause. A model with photosynthesis as possible input is useful, but my claim must leave respiration and exchange undetermined. I therefore reject my possible stronger production interpretation and plan initial/endpoint, duration and controls for that question without inventing them retrospectively. This is a worked own-analysis model response, not a physical measurement performed here.')
a['freshTransfer']=pair(
 'Für einen späteren neuen Datensatz lauten Rohanzeigen erneut 7,9/8,0/8,1 mg/L; die tatsächlich protokollierten Temperaturen sind diesmal 20/28/20 °C. Neue passende Referenzkarten zeigen Offsets +0,4 bei 20 °C und +1,2 bei 28 °C. Erzeuge deine eigene neue Korrekturtabelle samt Mittelwert und revidiere dein eigenes Protokoll. Dürfen die neuen Ergebnisse oder die alten 20-°C-Ergebnisse automatisch in dieselbe biologische Vergleichsaussage eingehen?',
 'For a later new dataset, raw readings are again 7.9/8.0/8.1 mg/L, but recorded temperatures are now 20/28/20 °C. New matching reference cards show offsets +0.4 at 20 °C and +1.2 at 28 °C. Produce your own new correction table and mean, and revise your own record. May the new and old 20 °C results automatically enter the same biological comparison?')
a['freshTransferWorkedResponse']=pair(
 'Meine neue Tabelle lautet 7,9−0,4=7,5; 8,0−1,2=6,8; 8,1−0,4=7,7 mg/L; mein Mittelwert ist 22,0/3≈7,33 mg/L. Ich schreibe Temperatur, Referenzzeitpunkt und bedingte Regel pro Zeile ins eigene Protokoll und nehme meine pauschale neue Korrektur−1,0 zurück. Reflexion meiner neuen Ergebnisauswahl: Der Mittelwert ist rechnerisch korrekt, aber drei verschiedene Bedingungen liefern keinen isolierten Beleuchtungs-/Biologievergleich; Temperatur beeinflusst auch Stoffwechsel und Löslichkeit. Die neuen Referenzen betreffen den neuen Zeitpunkt. Sie erlauben ohne historischen Kalibriernachweis keine rückwirkende Veränderung der alten Tabelle, deren ursprüngliche passende20-°C-Referenzen dokumentiert bleiben. Ich trenne alte und neue Auswertung und fordere passende kontrollierte Daten für eine gemeinsame Fragestellung. Die Korrektur erzeugt keine fehlenden Anfangs-/Zeitmessungen.',
 'My new table is 7.9−0.4=7.5; 8.0−1.2=6.8; 8.1−0.4=7.7 mg/L, with mean 22.0/3≈7.33 mg/L. I add temperature, reference time and conditional rule for each row to my own record and retract my blanket new −1.0 correction. Reflecting my own result selection: the mean is arithmetically correct, but differing conditions do not provide an isolated illumination/biological comparison; temperature also affects metabolism and solubility. The new references belong to the new time. Without historical calibration evidence they do not justify retrospectively changing the old table, whose matching initial 20 °C references remain documented. I separate old and new analysis and require matching controlled data for a joint question. Correction supplies no missing initial/time measurements.')
a['rubric']=[pair('Eigene Tabelle, Regel, Mittel/Spannweite und eigene begrenzte Ergebnisentscheidung vollständig erzeugt; Fremdkritik allein genügt nicht.','Produces own complete table, rule, mean/range and bounded result decision; criticism of another claim alone is insufficient.'),pair('Reflexion bezieht Gültigkeit, Offset/Streuung und Modellgrenzen konkret auf eigene Werte und eigene Entscheidungen.','Reflection explicitly applies validity, offset/spread and model limits to one’s own values and decisions.'),pair('Frische Variation erzeugt eigene neue Zeilen/7,33-Ergebnis und begründete eigene Revision ohne nachträgliches Erfinden alter Daten.','Fresh variation produces own new rows/7.33 result and justified own revision without retrospectively inventing old data.')]
b['material']=pair(
 'Konstruiertes Blatt-Datenmaterial für dein eigenes Analyse-/Modellprotokoll: Unter konstanten Modellbedingungen besitzen Trainingskarten T1/T2/T3 je 5/10/15 gleich große offene Poren und verlieren 10/20/30 relative Wassereinheiten/h. Eine unabhängige Prüfkarte H hat zunächst 20 als offen klassifizierte Poren und einen konstruierten Verlust von 30 Einheiten/h. Zwei der H-Poren sind aufgrund anderer Aufnahmebeleuchtung unsicher; deshalb ist die plausible Zahl offener Poren 18–20. Temperatur, Luftbewegung und Blattfläche sind für den Modellvergleich als konstant vorgegeben; Porenweite/Cuticula sind nicht gemessen. Erstelle aus diesen Angaben selbst ein einfaches Modell W=kN, prüfe es und protokolliere eigene Entscheidungen. Keine Karte ist eine hier durchgeführte reale Blattmessung.',
 'Constructed leaf data for your own analysis/model record: under fixed model conditions, training cards T1/T2/T3 have 5/10/15 equally sized open pores and lose 10/20/30 relative water units/h. An independent test card H initially has 20 pores classified as open and a constructed loss of 30 units/h. Two H pores are uncertain because recording illumination differs, so a plausible open-pore count is 18–20. Temperature, airflow and leaf area are fixed for this model comparison, while pore width/cuticle were not measured. Produce your own simple W=kN model, test it and record your own decisions. No card is a real leaf measurement performed here.')
b['task']=pair(
 'Erzeuge zuerst selbst k aus den Trainingskarten, deine eigene Vorhersage für H, den Residualwert und eine eigene Tabelle/Modellentscheidung. Reflektiere anschließend genau deinen eigenen Erkenntnisweg: Warum wähltest du diese Daten und dieses Modell? Wie wirken unsichere Klassifikation, fehlende biologische Wege und Abweichung auf die Gültigkeit deiner eigenen Vorhersage? Begründe eine prüfbare nächste Auswertung; bloße allgemeine Kritik des Blattmodells genügt nicht.',
 'First produce k from the training cards, your own H prediction, residual and own table/model decision. Then reflect that specific own inquiry: why did you choose those data and that model? How do uncertain classification, omitted biological pathways and mismatch affect the validity of your own prediction? Justify a testable follow-up analysis; generic leaf-model criticism alone is insufficient.')
b['workedResponse']=pair(
 'Mein eigenes Protokoll: Ich wähle T1–T3 zur Parameterbildung und halte H als unabhängige Prüfung zurück. Meine Quotienten10/5,20/10,30/15 ergeben jeweils k=2 Einheiten/(h·offene Pore). Ich entscheide mich zunächst für W=2N unter gleichen Porengrößen/Umgebungsbedingungen. Meine eigene H-Tabelle hat N=20, Vorhersage40, Kartenwert30 Einheiten/h und Residuum beobachtet−vorhergesagt=−10, also25 % der Vorhersage40. Meine Ergebnisentscheidung ist: Trainingspassung gut, Vorhersage auf H verfehlt, kein bestätigtes allgemeines reales Blattgesetz. Reflexion meiner eigenen Auswahl und Rechnung: Wenn ich k nachträglich an H anpasse, verliert meine unabhängige Prüfung ihren Sinn. Unsichere KlassifikationN18–20 ergibt meine Vorhersagespanne36–40; der Kartenwert30 liegt weiterhin darunter, doch Porenweite oder andere nicht gemessene Bedingungen können die Abweichung mitverursachen. Gleich gezählte Poren sind biologisch nicht notwendig gleich leitfähig. Cuticula, Blattfläche, Luftfeuchte und Luftbewegung sind mögliche weitere Wege/Bedingungen; ihre Beiträge sind mit diesen Karten nicht identifiziert. Mein einfaches Modell zeigt einen Zusammenhang und erzeugt prüfbare eigene Vorhersagen; es ist für die vorhandenen Karten begrenzt und ersetzt keine echte Messung. Ich protokolliere getrennt meine Parameterwahl, Klassifikationsunsicherheit, Ergebnis und verworfene Allgemeinbehauptung und plane standardisierte Bilder plus unabhängige passend kontrollierte Prüfkarten.',
 'My own record: I use T1–T3 to determine parameters and reserve H as an independent test. My ratios10/5,20/10,30/15 each give k=2 units/(h·open pore). I initially choose W=2N with matching pore sizes/environment. My own H table contains N=20, prediction40, card value30 units/h and observed-minus-predicted residual−10, or25 % of the prediction40. My result decision is: good training fit, missed H prediction, no confirmed general real-leaf law. Reflecting my own selection/calculation: retrospectively fitting k to H would remove its independent-test purpose. Uncertain N18–20 yields my prediction interval36–40; card value30 remains below it, but pore width or other unmeasured conditions may contribute to mismatch. Equal counts do not imply equal conductance. Cuticle, area, humidity and airflow are possible pathways/conditions whose contributions these cards do not identify. My simple model shows a relationship and produces testable own predictions, but is bounded for these cards and replaces no actual measurement. I separately record parameter choice, classification uncertainty, result and rejected generalization, and plan standardized images plus independent appropriately controlled test cards.')
b['freshTransfer']=pair(
 'Neue unabhängige konstruierte Karten bei geprüfter gleicher Porenweite und Umgebung geben N=0/10/20 und W=5/25/45 Einheiten/h. Erzeuge dein eigenes erweitertes Modell aus diesen Karten und eine frische eigene Vorhersage für N=15. Reflektiere, welche deiner früheren Entscheidungen zu revidieren sind und ob die Zusatz5 alleine die Cuticula als Ursache beweist.',
 'New independent constructed cards with checked matching pore width/environment give N=0/10/20 and W=5/25/45 units/h. Produce your own extended model and fresh own prediction for N=15. Reflect which earlier decisions require revision and whether the additional5 alone proves cuticle as the cause.')
b['freshTransferWorkedResponse']=pair(
 'Meine eigene neue Auswertung: N0 liefert Basis5, (25−5)/10 und (45−5)/20 liefern beide Steigung2. Ich ändere mein protokolliertes Modell zu W=2N+5 und sage selbst für N15 den Wert35 Einheiten/h voraus; als nächste Prüfung lasse ich eine dafür unabhängige Karte offen. Ich revidiere ausdrücklich meine eigene Annahme W0=0, nicht automatisch die bisherige Steigung2. Die Zusatz5 ist mit einem porenunabhängigen Weg vereinbar, beweist aber ohne getrennten Nachweis nicht allein Cuticula. Ich dokumentiere die neue Modellentscheidung und die Grenze, dass passende Daten über bestimmte Bedingungen keine universelle Blatterklärung sind. Den alten H-Wert30 darf ich nicht passend zu35 umschreiben: Er gehört zu einer anderen Karte/Bedingungsprüfung und bleibt als Abweichung erhalten.',
 'My own new analysis: N0 supplies baseline5; (25−5)/10 and (45−5)/20 both give slope2. I revise my recorded model to W=2N+5 and make my own N15 prediction35 units/h, leaving an independent card for its next test. I explicitly revise my own W0=0 assumption rather than automatically rejecting slope2. The additional5 is consistent with a pore-independent pathway but does not alone establish cuticle without a separate test. I record the new model decision and the limit that matching data under particular conditions are not a universal leaf explanation. I must not rewrite old H value30 to fit35: it is a different card/condition test and remains a mismatch.')
b['rubric']=[pair('Eigene Parameter-/Trainings-/Prüftabelle, Vorhersage40 und eigenes Residuum−10 korrekt erzeugt und Datenwahl dokumentiert.','Correctly produces own parameter/training/test table, prediction40 and own residual−10 with documented data selection.'),pair('Gültigkeits-, Klassifikations- und Modellreflexion beziehen sich auf die eigene Auswahl/Vorhersage und begrenzen die eigene Ergebnisbehauptung.','Validity, classification and model reflection address one’s own selection/prediction and bound one’s own result claim.'),pair('Erzeugt selbst erweitertes Modell2N+5/35-Vorhersage, reflektiert eigene Revision und erhält historischen Gegenbefund statt ihn umzuschreiben.','Produces own extended2N+5 model/35 prediction, reflects own revision and retains the historical counterfinding rather than rewriting it.')]
e['modelLimits']=['Eigene Ergebnisse sind selbst erzeugte Auswertungen/Modellentscheidungen aus konstruierten Rohkarten, keine reale physische Untersuchung oder tatsächlichen Lernendenresultate.','Beide Fälle verlangen zwingend zuerst eigene Ergebnisse/Protokolle und danach ausdrückliche Reflexion genau dieser eigenen Entscheidungen einschließlich Datenvalidität, Fehlerquellen und Modellgrenzen.']
write('whole-fourteen-twenty-nine-cases.only-P11-own-results.candidate.json',materials)
briefs=[]
for c in e['authoredCases']:
 briefs.append(dict(id=c['caseId'],taskDemandDe=c['material']['de']+'\n\nAuftrag: '+c['task']['de']+'\n\nFrische Variation: '+c['freshTransfer']['de'],taskDemandEn=c['material']['en']+'\n\nTask: '+c['task']['en']+'\n\nFresh variation: '+c['freshTransfer']['en'],expectedPerformanceDe=c['workedResponse']['de']+'\n\nTransferantwort: '+c['freshTransferWorkedResponse']['de'],expectedPerformanceEn=c['workedResponse']['en']+'\n\nTransfer response: '+c['freshTransferWorkedResponse']['en'],understandingFocusDe=' '.join(x['essentialUnderstandingDe'] for x in exps)+' Rubrik: '+'; '.join(r['de'] for r in c['rubric']),understandingFocusEn=' '.join(x['essentialUnderstandingEn'] for x in exps)+' Rubric: '+'; '.join(r['en'] for r in c['rubric'])))
# Exact technical contract: concise P briefs, with full independent case bodies retained separately.
briefs[0]['expectedPerformanceDe']='Erzeuge zuerst deine eigene Tabelle mit Roh-/Korrekturspalten: Offset=8,0−7,0=+1,0; bei passenden stabilen20-°C-Referenzen gilt korrigiert=roh−1,0. Eigene Zeilen7,9→6,9;8,0→7,0;8,1→7,1 mg/L, eigener Mittelwert7,0 und Spannweite0,2. Dokumentiere deine Regel und entscheide selbst, nur korrigierte Endkonzentrationen zu berichten. Reflektiere genau eigene Werte/Entscheidungen: kleine Streuung beweist keine Genauigkeit; systematischer Offset ist nicht zufällige Variation. Deine Berechnung liefert keine fehlenden Anfangswerte, Atmung, Austausch oder Dauer, also keine Zunahme/Produktionsrate und keine alleinige Fotosyntheseursache. Begrenze deine Modellentscheidung und protokolliere verworfene stärkere Deutung sowie benötigte kontrollierte Nachprüfung. Frische Variation: Erzeuge mit Temperaturen20/28/20 und Offsets0,4/1,2/0,4 die eigene neue Tabelle7,5/6,8/7,7, Mittel22/3≈7,33 mg/L. Revidiere deine pauschale neue−1,0-Regel, dokumentiere temperatur-/zeitbezogene Entscheidungen. Reflektiere, dass unterschiedliche Temperaturen den biologischen Vergleich begrenzen; neue Referenzen ändern alte dokumentierte Kalibrierung nicht ohne historische Belege. Alte/neue Auswertungen getrennt erhalten, nichts rückwirkend erfinden. Eigene Auswertung aus fiktiven Karten, keine ausgeführte physische Messung.'
briefs[0]['expectedPerformanceEn']='First produce your own raw/correction table: offset8.0−7.0=+1.0; with matching stable20 °C references choose corrected=raw−1.0. Own rows7.9→6.9;8.0→7.0;8.1→7.1 mg/L, own mean7.0 and range0.2. Document your rule and choose to report corrected endpoints only. Reflect those own values/decisions: low spread does not prove accuracy; systematic offset differs from random variation. Your calculation supplies no missing initial value, respiration, exchange or duration, hence no increase/rate or sole photosynthesis cause. Bound your model decision and record the rejected stronger interpretation plus controlled follow-up needed. Fresh variation: with temperatures20/28/20 and offsets0.4/1.2/0.4 produce your own new table7.5/6.8/7.7 and mean22/3≈7.33 mg/L. Revise your blanket new−1.0 rule and record temperature/time-linked decisions. Reflect that different temperatures limit biological comparison; new references do not retrospectively change old documented calibration without historical evidence. Retain separate old/new analyses without inventing missing data. Own analysis of fictitious cards, no physical measurement performed.'
briefs[1]['expectedPerformanceDe']='Erzeuge selbst ein Analyse-/Entscheidungsprotokoll: T1–T3 zur Parameterwahl, H als unabhängige Prüfung. Eigene Quotienten10/5=20/10=30/15=2 ergeben k2; wähle W=2N mit dokumentierten Bedingungen. Eigene H-Tabelle:N20, Vorhersage40, Kartenwert30 Einheiten/h, Residuum−10=25%der Vorhersage40. Entscheide selbst: Trainingspassung, aber verfehlte Prüfung; kein allgemeines reales Blattgesetz. Reflektiere deine eigene Auswahl/Vorhersage: nachträgliche H-Anpassung entwertet unabhängige Prüfung. Unsicheres N18–20 ergibt eigene Spanne36–40, weiterhin oberhalb30. Porenweite, Cuticula und Umgebung sind nicht dadurch bestimmt; gleiche Zählung bedeutet keine gleiche Leitfähigkeit. Dokumentiere Gültigkeits-/Klassifikationsgrenzen deiner eigenen Aussage und passende unabhängige Nachprüfung. Frische Variation: Aus N0/10/20 und W5/25/45 erzeuge selbst Basis5, Steigung2 und das eigene Modell W=2N+5; deine frische N15-Vorhersage ist35. Reflektiere ausdrücklich eigene Revision der Nullbasis, nicht automatisch der Steigung. Zusatz5 ist mit porenunabhängigem Weg vereinbar, beweist Cuticula aber nicht. Historischen H-Wert30 unverändert erhalten, neue unabhängige Karte für35 planen. Eigene Modellresultate aus konstruierten Rohkarten, keine reale Messung.'
briefs[1]['expectedPerformanceEn']='Produce your own analysis/decision record: choose T1–T3 for parameters and reserve H for independent testing. Own ratios10/5=20/10=30/15=2 give k2; choose W=2N under documented conditions. Own H table:N20, prediction40, card value30 units/h, residual−10=25%of prediction40. Make your own decision: training fit but failed test, no general real-leaf law. Reflect your selection/prediction: retrospectively fitting H removes independent testing. Uncertain N18–20 yields your own36–40 interval, still above30. Pore width, cuticle and environment are not thereby identified; equal counts need not mean equal conductance. Record validity/classification limits of your own claim and suitable independent follow-up. Fresh variation: from N0/10/20 and W5/25/45 produce baseline5, slope2 and your own W=2N+5 model; your fresh N15 prediction is35. Explicitly reflect your revision of the zero baseline rather than automatically rejecting slope. Additional5 fits a pore-independent pathway without proving cuticle. Preserve historical H value30 and plan an independent card for35. Own modeled results from constructed raw cards, no real measurement.'
assert all(len(b[k])<=2000 for b in briefs for k in ['expectedPerformanceDe','expectedPerformanceEn'])
